window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"strawberry":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"草莓"}],"examples":[{"sentence":"The grower covered each strawberry bed before the frost, because early flowers are easily damaged by sudden cold.","translation":"种植者在霜冻前覆盖每块草莓苗床，因为早期开花容易受突发低温损害。","targetForm":"strawberry","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the strawberry harvest began late, warm days in June produced fruit with an unusually rich flavour.","translation":"尽管草莓收获开始较晚，六月温暖天气仍产出了风味异常浓郁的果实。","targetForm":"strawberry","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The chef paired strawberry with basil, which gave the dessert a fresh contrast rather than an overly sweet taste.","translation":"厨师将草莓与罗勒搭配，使甜点呈现清新对比而不过分甜腻。","targetForm":"strawberry","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Researchers compared several strawberry varieties to identify which plants remained productive under warmer summer conditions.","translation":"研究人员比较多个草莓品种，以确定哪些植株在更温暖夏季条件下仍能保持产量。","targetForm":"strawberry","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The market sold locally grown strawberries, whose short journey from field to stall helped preserve their delicate texture.","translation":"市场出售本地种植的草莓，田间到摊位的短运输有助于保持其细腻口感。","targetForm":"strawberries","senseId":"source-n-1","sourceSenseId":"n-1"}]},"stall":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"厩"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"货摊"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"拖延"},{"id":"source-v-8","partOfSpeech":"v.","sourceSenseIds":["v-8"],"sense":"停止"}],"examples":[{"sentence":"The stable kept each horse in a clean stall where staff could check its food and bedding every morning.","translation":"马厩把每匹马安置在干净的马栏中，工作人员每天早晨检查食物和垫料。","targetForm":"stall","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the market stall was small, it attracted customers by selling bread from nearby family bakeries.","translation":"尽管市场货摊很小，它仍靠售卖附近家庭面包店的面包吸引顾客。","targetForm":"stall","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The manager recognised the delay as a stall and asked the supplier to provide a clear date for delivery.","translation":"经理认为这一延误是在拖延，并要求供应商给出明确交货日期。","targetForm":"stall","senseId":"source-n-6","sourceSenseId":"n-6"},{"sentence":"Because the discussion had stalled, the chair summarised the points of agreement before asking for new proposals.","translation":"由于讨论陷入停滞，主席在征求新提案前总结了已达成一致的要点。","targetForm":"stalled","senseId":"source-v-8","sourceSenseId":"v-8"},{"sentence":"The project will stall unless the team decides who is responsible for checking the final evidence.","translation":"除非团队决定谁负责核查最终证据，否则项目将停滞。","targetForm":"stall","senseId":"source-v-8","sourceSenseId":"v-8"}]},"steak":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"牛排"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"鱼排"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"肉排"}],"examples":[{"sentence":"The menu described the steak clearly, including its source and the vegetables that would be served beside it.","translation":"菜单清楚描述了这份牛排，包括其来源以及将搭配的蔬菜。","targetForm":"steak","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the steak was the most popular dish, the restaurant also offered several vegetarian choices for guests.","translation":"尽管牛排是最受欢迎的菜肴，这家餐厅也为客人提供多种素食选择。","targetForm":"steak","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The chef used a steak of fish in the demonstration to show how different textures could be presented simply.","translation":"厨师在演示中使用一块鱼排，展示如何简洁地呈现不同质地。","targetForm":"steak","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Before the event, the kitchen labelled every steak so that dietary orders could be checked accurately.","translation":"活动前，厨房给每块肉排贴上标签，以便准确核查饮食订单。","targetForm":"steak","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The documentary followed the journey of a steak from a local producer to a busy city restaurant.","translation":"这部纪录片追踪了一块牛排从本地生产者到繁忙城市餐厅的旅程。","targetForm":"steak","senseId":"source-n-1","sourceSenseId":"n-1"}]},"stool":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"凳子"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"粪便"}],"examples":[{"sentence":"The artist sat on a simple wooden stool while sketching the bustling market scene, her posture relaxed yet attentive.","translation":"艺术家坐在一张简单的木凳上，描绘着熙熙攘攘的市场景象，她的姿态放松而专注。","targetForm":"stool","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In the minimalist kitchen, a set of three sleek metal stools lined the breakfast bar, their design both functional and elegant.","translation":"在极简风格的厨房里，三张时尚的金属凳子排列在早餐吧台前，其设计既实用又优雅。","targetForm":"stools","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The laboratory analysis of the patient's stool sample revealed the presence of a bacterial pathogen, which explained the persistent digestive symptoms.","translation":"对患者粪便样本的实验室分析揭示了细菌病原体的存在，这解释了持续的消化症状。","targetForm":"stool","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Doctors often recommend a stool test to diagnose certain gastrointestinal disorders, as it provides crucial information about digestive health.","translation":"医生经常建议进行粪便检测以诊断某些胃肠道疾病，因为它提供了关于消化健康的关键信息。","targetForm":"stool","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The veterinarian examined the dog's stools for signs of parasites, a routine procedure during the annual health check-up.","translation":"兽医检查了狗的粪便以寻找寄生虫的迹象，这是年度健康检查中的常规程序。","targetForm":"stools","senseId":"source-n-3","sourceSenseId":"n-3"}]},"star":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"星"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"恒星"}],"examples":[{"sentence":"If you cry because you miss the sun when it goes away, then you will also miss the stars.","translation":"如果，错过太阳的时候你在流泪，那么你也将错过群星。","targetForm":"stars","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"You can see the stars with your naked eye, and even better through a telescope.","translation":"你可以用肉眼观星，用望远镜的话，还能看得更清楚。","targetForm":"stars","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"That tiny star there is the brightest out of all the stars.","translation":"那儿的小星星是所有星星里最亮的。","targetForm":"star","senseId":"source-n-2","sourceSenseId":"n-2"}]},"stove":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"火炉"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"窑"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"用火炉烤"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"stave的过去式和过去分词"}],"examples":[{"sentence":"She placed the kettle on the cast-iron stove to boil water for tea.","translation":"她把水壶放在铸铁火炉上烧水泡茶。","targetForm":"stove","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The potter carefully loaded the clay pots into the wood-fired stove for glazing.","translation":"陶工小心翼翼地将陶罐装入烧木柴的窑中进行上釉。","targetForm":"stove","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"In the old workshop, they stoved the wooden planks to dry them thoroughly.","translation":"在旧作坊里，他们用火炉烘烤木板，使其彻底干燥。","targetForm":"stoved","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The chef stoves the peppers over an open flame to enhance their smoky flavor.","translation":"厨师在明火上用火炉烤辣椒，以增强其烟熏风味。","targetForm":"stoves","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"He had stove in the barrel's lid with a heavy mallet during the struggle.","translation":"在搏斗中，他用沉重的木槌砸穿了桶盖。","targetForm":"stove","senseId":"source-v-2","sourceSenseId":"v-2"}]},"stubborn":{"senseGroups":[{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"棘手的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"顽固的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"执拗的"}],"examples":[{"sentence":"Although the stubborn stain seemed impossible to remove, a combination of enzymatic cleaners eventually restored the fabric.","translation":"尽管顽固的污渍似乎无法去除，但酶清洁剂的组合最终恢复了织物。","targetForm":"stubborn","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"While a stubborn adherence to tradition can preserve cultural heritage, it may also hinder necessary social progress.","translation":"虽然顽固坚持传统可以保护文化遗产，但也可能阻碍必要的社会进步。","targetForm":"stubborn","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because the negotiator maintained a stubborn position on key issues, the peace talks collapsed after weeks of deadlock.","translation":"由于谈判者在关键问题上保持顽固立场，和平谈判在数周僵局后破裂。","targetForm":"stubborn","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Stubborn resistance to change, which often stems from fear of the unknown, can prevent organizations from adopting innovative practices.","translation":"顽固抵制变革，往往源于对未知的恐惧，会阻碍组织采用创新做法。","targetForm":"stubborn","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The stubborn persistence of gender inequality in the workplace calls for comprehensive policies that address both cultural and structural barriers.","translation":"工作场所性别不平等的顽固存在要求制定全面的政策，以解决文化和结构性障碍。","targetForm":"stubborn","senseId":"source-adj-4","sourceSenseId":"adj-4"}]},"statue":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"雕像"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"以雕像装饰"}],"examples":[{"sentence":"The statue of the university's founder stands in the central plaza and recalls the institution's early values.","translation":"大学创始人的雕像矗立在中央广场，令人想起这所机构早期的价值观。","targetForm":"statue","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the ancient statue was carved from one block of marble, it has survived for two millennia.","translation":"由于这座古代雕像由整块大理石雕成，它已保存两千年。","targetForm":"statue","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the bronze statue depicts a controversial figure, it remains a protected cultural artefact.","translation":"尽管这座铜像刻画的是一位有争议的人物，它仍是受保护的文化文物。","targetForm":"statue","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When the statue was unveiled, the community gathered to reflect on the history it represented.","translation":"雕像揭幕时，社区居民聚集起来思考它所代表的历史。","targetForm":"statue","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The architect planned to statue the garden entrance with figures drawn from local history.","translation":"建筑师计划用取材于当地历史的人物雕像装饰花园入口。","targetForm":"statue","senseId":"source-v-1","sourceSenseId":"v-1"}]},"stiff":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"坚硬的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"严厉的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"呆板的"},{"id":"source-adj-6","partOfSpeech":"adj.","sourceSenseIds":["adj-6"],"sense":"强烈的"},{"id":"source-adj-8","partOfSpeech":"adj.","sourceSenseIds":["adj-8"],"sense":"稠的"}],"examples":[{"sentence":"The old leather boots had become so stiff that he could barely force his feet into them.","translation":"那双旧皮靴变得如此僵硬，以至于他几乎无法把脚塞进去。","targetForm":"stiff","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The judge imposed a stiff sentence on the repeat offender, reflecting the severity of the crime.","translation":"法官对那名惯犯判处了严厉的刑罚，反映了罪行的严重性。","targetForm":"stiff","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"His stiff demeanor at the formal dinner made it difficult for others to engage him in casual conversation.","translation":"他在正式晚宴上拘谨的举止使他人难以与他进行轻松的交谈。","targetForm":"stiff","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Despite the stiff competition from established firms, the startup managed to secure a significant market share.","translation":"尽管面临来自老牌公司的激烈竞争，这家初创公司仍成功获得了可观的市场份额。","targetForm":"stiff","senseId":"source-adj-6","sourceSenseId":"adj-6"},{"sentence":"The batter was too stiff to pour, so she added a splash of milk to thin it out.","translation":"面糊太稠了，倒不出来，所以她加了一点牛奶稀释。","targetForm":"stiff","senseId":"source-adj-8","sourceSenseId":"adj-8"}]},"stomach":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"肚子"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"胃"}],"examples":[{"sentence":"Because my stomach was upset, I took a day off school.","translation":"因为肚子不舒服， 我请了一天假不去学校。","targetForm":"stomach","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"I developed a tumor in my stomach, which required surgery.","translation":"我得了胃肿瘤，必须动手术切除。","targetForm":"stomach","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"All of a sudden, I felt a sharp pain in my stomach.","translation":"我突然肚痛得要命。","targetForm":"stomach","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"I got a stomach tumor and had to have it operated on.","translation":"我得了胃肿瘤，必须动手术切除。","targetForm":"stomach","senseId":"source-n-1","sourceSenseId":"n-1"}]},"start":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"开端"}],"examples":[{"sentence":"That is why we need to start thinking of education as a security issue.","translation":"这就是我们需要开始把教育视为安全问题的原因。","targetForm":"start","senseId":"source-n-3","sourceSenseId":"n-3"}]},"steel":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"钢"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"钢铁"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"钢制的"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使坚强"}],"examples":[{"sentence":"Because steel is durable and recyclable, it remains central to sustainable construction around the world.","translation":"由于钢材耐用且可回收，它仍是全球可持续建筑的核心材料。","targetForm":"steel","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The automotive industry uses high-strength steel to reduce vehicle weight and improve fuel efficiency.","translation":"汽车行业使用高强度钢材来减轻车重并提高燃油效率。","targetForm":"steel","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although steel production consumes much energy, new technology has reduced its carbon footprint.","translation":"尽管钢铁生产消耗大量能源，新技术已减少其碳足迹。","targetForm":"steel","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The bridge relied on a steel framework that could withstand heavy traffic and strong winds.","translation":"这座桥依靠能承受繁忙交通和强风的钢制框架。","targetForm":"steel","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Years of difficult negotiations steeled the diplomat for the pressure of the final summit.","translation":"多年的艰难谈判使这位外交官坚强起来，能够承受最终峰会的压力。","targetForm":"steeled","senseId":"source-v-1","sourceSenseId":"v-1"}]},"stranger":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"陌生人"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"门外汉"}],"examples":[{"sentence":"The kindness of a stranger, who offered directions when she was lost, restored her faith in humanity.","translation":"一个陌生人的善意，在她迷路时为她指路，恢复了她对人性的信心。","targetForm":"stranger","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While a stranger may seem intimidating at first, engaging in conversation often reveals shared interests and perspectives.","translation":"尽管陌生人起初可能令人生畏，但进行交谈往往会揭示共同的兴趣和观点。","targetForm":"stranger","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because she was a stranger to the local language, she enrolled in an intensive course to communicate effectively.","translation":"由于她对当地语言一窍不通，她报名参加了一个强化课程以便有效沟通。","targetForm":"stranger","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"To ensure that no stranger feels excluded, the community center organizes weekly social events for newcomers.","translation":"为了确保没有陌生人感到被排斥，社区中心每周为新来者组织社交活动。","targetForm":"stranger","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although he was a stranger to the city, he navigated the complex subway system by using a detailed map.","translation":"尽管他对这个城市很陌生，但他通过使用详细的地图成功乘坐了复杂的地铁系统。","targetForm":"stranger","senseId":"source-n-2","sourceSenseId":"n-2"}]},"stain":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"污点"}],"examples":[{"sentence":"A coffee stain on the document made several words illegible, which caused delays in processing the application.","translation":"文件上的咖啡渍使几个字难以辨认，这导致申请处理延迟。","targetForm":"stain","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The scandal left a permanent stain on his political career, thereby ending his chances of re-election.","translation":"丑闻给他的政治生涯留下了永久的污点，从而终结了他连任的机会。","targetForm":"stain","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The wooden table acquired a dark stain from years of use, although it was regularly polished.","translation":"木桌因多年使用而留下了深色污迹，尽管它定期上光。","targetForm":"stain","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the fabric was treated with a protective coating, a faint stain remained after washing.","translation":"尽管布料经过保护涂层处理，洗涤后仍留有淡淡的污渍。","targetForm":"stain","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Using a special solvent, she removed the oil stain from the concrete floor, which had been there for weeks.","translation":"她用一种特殊的溶剂清除了水泥地上的油渍，这油渍已存在数周。","targetForm":"stain","senseId":"source-n-2","sourceSenseId":"n-2"}]},"stare":{"senseGroups":[{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"盯"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"瞪视"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"注视"}],"examples":[{"sentence":"It's embarrassing to be seen without make-up so please don't stare.","translation":"素颜太害羞了，请不要盯着我看。","targetForm":"stare","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"My manager stared at me as if he was angry.","translation":"经理像是生气了一样盯着我。","targetForm":"stared","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"You might as well read a novel instead of staring at the ceiling.","translation":"望着天花板发呆,还不如读一读小说。","targetForm":"staring","senseId":"source-v-1","sourceSenseId":"v-1"}]},"steward":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"管家"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"管理人"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"乘务员"}],"examples":[{"sentence":"The chief steward coordinated the event with such precision that every guest felt welcomed and attended to.","translation":"总管事如此精确地协调了活动，以至于每位客人都感到受欢迎和照顾。","targetForm":"steward","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"As a steward of the company's resources, the CFO must balance risk and opportunity to ensure long-term growth.","translation":"作为公司资源的管理者，首席财务官必须平衡风险与机遇，以确保长期增长。","targetForm":"steward","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The steward on the train efficiently managed the dining car, which enhanced the overall travel experience for passengers.","translation":"火车上的乘务员高效地管理餐车，这提升了乘客的整体旅行体验。","targetForm":"steward","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"In the absence of a dedicated steward, the estate fell into disrepair, which illustrates the importance of responsible management.","translation":"由于缺乏专门的管家，庄园年久失修，这说明了负责任管理的重要性。","targetForm":"steward","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because the environmental steward advocated for stricter regulations, the local ecosystem began to recover.","translation":"因为环境管理者倡导更严格的法规，当地生态系统开始恢复。","targetForm":"steward","senseId":"source-n-1","sourceSenseId":"n-1"}]},"station":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"车站"}],"examples":[{"sentence":"When he reached the station, the train had already left almost half an hour before.","translation":"他到了火车站的时候，火车已经开出了差不多半小时。","targetForm":"station","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"At the train station, once I had figured out where the queue for tickets actually was, I began the long wait.","translation":"在车站，我把排队买票的地点弄清楚后，开始久等。","targetForm":"station","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"There's a train station in Japan where the station master is a cat.","translation":"在日本，有站长是猫的车站。","targetForm":"station","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"She hurried to the station so that she wouldn't miss the train.","translation":"她匆忙赶去车站，以免错过火车。","targetForm":"station","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I only got to the station after the train had left.","translation":"我在火车开后才到达车站。","targetForm":"station","senseId":"source-n-1","sourceSenseId":"n-1"}]},"student":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"学生"}],"examples":[{"sentence":"We also must expand our capacity to host refugees through resettlement and other legal pathways – such as student, work, and family reunification visas.","translation":"我们还必须扩大我们通过安置及其他合法途径接纳难民的能力 — — 包括发放留学、工作签证和家庭团聚签证。","targetForm":"student","senseId":"source-n-1","sourceSenseId":"n-1"}]},"strenuous":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"艰苦的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"费劲的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"奋发的"}],"examples":[{"sentence":"The researchers undertook a strenuous investigation that required meticulous data collection over several months.","translation":"研究人员进行了一项艰苦的调查，需要在数月内进行细致的数据收集。","targetForm":"strenuous","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"She maintained a strenuous exercise regimen, which included daily running and weightlifting sessions.","translation":"她坚持费劲的锻炼计划，包括每天跑步和举重训练。","targetForm":"strenuous","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"The team's strenuous efforts to meet the deadline were evident in their late-night work sessions.","translation":"团队为赶上截止日期而付出的奋发努力在他们深夜的工作中显而易见。","targetForm":"strenuous","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Climbing the steep mountain proved to be a strenuous task that tested the hikers' endurance.","translation":"攀登陡峭的山峰是一项艰苦的任务，考验了徒步者的耐力。","targetForm":"strenuous","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The government launched a strenuous campaign to promote public health awareness across the nation.","translation":"政府发起了一场奋发的运动，以提高全国的公共卫生意识。","targetForm":"strenuous","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"store":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"商店"}],"examples":[{"sentence":"Only if you put up a different sign can you become a miscellany store.","translation":"只要换上不同招牌，就能成为各种商店。","targetForm":"store","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Thankfully, there was an Armani store just outside the alley where Dima had slept.","translation":"幸好，在狄马睡觉的小巷外面，刚好有一家阿玛尼。","targetForm":"store","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I bought a VCR at that store for a low price.","translation":"我在那商店花低价买了台录像机。","targetForm":"store","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Everything at that store is 10 percent off the regular price.","translation":"那商店里的商品全都打九折呢。","targetForm":"store","senseId":"source-n-1","sourceSenseId":"n-1"}]},"stalk":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"茎"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"追踪"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"蔓延"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"高视阔步"}],"examples":[{"sentence":"Because the stalk stores water, the plant can survive long dry periods without regular irrigation.","translation":"由于茎能储存水分，这种植物无需定期灌溉也能挺过长期干旱。","targetForm":"stalk","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The botanist measured each stalk before comparing how the plants responded to different light levels.","translation":"植物学家测量了每根茎，然后比较植物对不同光照水平的反应。","targetForm":"stalk","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When photographers stalk wildlife, they should keep a respectful distance and avoid disturbing its habitat.","translation":"当摄影师跟踪野生动物时，应保持尊重的距离，避免干扰其栖息地。","targetForm":"stalk","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"The rumour began to stalk the office after an unclear announcement created anxiety among employees.","translation":"一则不明确的通知引发员工焦虑后，谣言开始在办公室蔓延。","targetForm":"stalk","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Although he was frustrated, he refused to stalk out of the meeting before hearing the final decision.","translation":"尽管他感到沮丧，他仍没有气冲冲地走出会议室，而是听完了最终决定。","targetForm":"stalk","senseId":"source-v-4","sourceSenseId":"v-4"}]},"straight":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"直"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"直线"}],"examples":[{"sentence":"Although the road was long and straight, the driver remained cautious because dense fog reduced visibility significantly.","translation":"尽管道路又长又直，但由于浓雾大大降低了能见度，司机仍保持谨慎。","targetForm":"straight","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The architect designed the bridge with a straight alignment, thereby minimizing construction costs and maximizing structural efficiency.","translation":"建筑师将桥梁设计成直线走向，从而最大限度地降低了建造成本并提高了结构效率。","targetForm":"straight","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In geometry, a straight is the shortest distance between two points, a concept that underpins many engineering applications.","translation":"在几何学中，直线是两点之间的最短距离，这一概念是许多工程应用的基础。","targetForm":"straight","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"After months of investigation, the journalist finally got the facts straight, which allowed her to publish a comprehensive report.","translation":"经过数月的调查，记者终于弄清了事实，这使她得以发表一份全面的报道。","targetForm":"straight","senseId":"source-n-2","sourceSenseId":"n-2"}]},"strong":{"senseGroups":[{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"有力的"}],"examples":[{"sentence":"The question now is whether Western institutions are strong enough to contain the global plutocracy that low interest rates have wrought.","translation":"现在的问题是西方制度是否足够强大，能够遏制低利率所造就的全球财阀。","targetForm":"strong","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"This puts a new debate center stage: how to reconcile increased action to reduce greenhouse gas emissions with strong economic growth.","translation":"这把一个新争论带到了舞台中央：如何协调越来越多的行动以降低伴随强劲经济增长出现的温室气体排放。","targetForm":"strong","senseId":"source-adj-5","sourceSenseId":"adj-5"}]},"stoop":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"佝偻"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"屈从"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"弯腰"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"堕落"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"弯下"}],"examples":[{"sentence":"The old gardener walked with a noticeable stoop, a consequence of decades spent tending the low flower beds.","translation":"老园丁走路时明显驼背，这是几十年照料低矮花坛的结果。","targetForm":"stoop","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Her habitual stoop when addressing the committee revealed a deep-seated reluctance to assert her own opinions.","translation":"她在对委员会讲话时习惯性的屈从姿态，暴露了她不愿坚持己见的根深蒂固心理。","targetForm":"stoop","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"To retrieve the fallen key, he had to stoop low beneath the heavy oak table, his knees protesting the sudden movement.","translation":"为了捡起掉落的钥匙，他不得不在沉重的橡木桌下深深弯腰，膝盖因这突然的动作而发出抗议。","targetForm":"stoop","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"A principled leader should never stoop to exploiting public fears for political gain, as such tactics erode democratic trust.","translation":"一位有原则的领导者绝不应堕落到利用公众恐惧来谋取政治利益，因为这种手段会侵蚀民主信任。","targetForm":"stoop","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The tall visitor stooped slightly as he entered the ancient cottage, whose low doorway had been built centuries ago.","translation":"高大的访客走进那座古老村舍时微微弯下身子，因为那低矮的门廊建于几个世纪前。","targetForm":"stooped","senseId":"source-v-1","sourceSenseId":"v-1"}]},"stocking":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"长袜"}],"examples":[{"sentence":"There is a pair of worn red stockings in the drawer.","translation":"抽屉里有一双穿过的红色丝袜。","targetForm":"stockings","senseId":"source-n-1","sourceSenseId":"n-1"}]},"stair":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"楼梯"}],"examples":[{"sentence":"Although the stair was steep and narrow, the elderly professor climbed it daily to maintain his health.","translation":"尽管楼梯又陡又窄，这位年迈的教授每天爬楼梯以保持健康。","targetForm":"stair","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When the fire alarm sounded, the crowd descended the stair in an orderly manner, thereby avoiding panic.","translation":"当火警响起时，人群有序地走下楼梯，从而避免了恐慌。","targetForm":"stair","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the elevator was under repair, all employees had to use the stair, which caused a brief delay.","translation":"由于电梯正在维修，所有员工不得不走楼梯，这导致了短暂的延误。","targetForm":"stair","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Installing a handrail along the stair is essential to ensure the safety of elderly residents in the building.","translation":"沿着楼梯安装扶手对于确保楼内老年居民的安全至关重要。","targetForm":"stair","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The architect designed a spiral stair that not only saved space but also added an artistic element to the lobby.","translation":"建筑师设计了一个螺旋楼梯，不仅节省了空间，还为大厅增添了艺术元素。","targetForm":"stair","senseId":"source-n-2","sourceSenseId":"n-2"}]},"strain":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"紧张"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"扭伤"}],"examples":[{"sentence":"The financial strain of supporting a family while pursuing a degree forced her to seek additional scholarships.","translation":"在攻读学位的同时养家糊口的经济压力迫使她寻求额外的奖学金。","targetForm":"strain","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the athlete ignored the early signs of muscle strain, a minor injury developed into a chronic condition.","translation":"由于运动员忽视了肌肉拉伤的早期迹象，小伤发展成了慢性病。","targetForm":"strain","senseId":"source-n-5","sourceSenseId":"n-5"}]},"statesman":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"政治家"}],"examples":[{"sentence":"The statesman argued that durable institutions matter more than short-lived popularity during periods of uncertainty.","translation":"这位政治家认为，在不确定时期，持久的制度比短暂的声望更重要。","targetForm":"statesman","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Rather than exploiting public anxiety, the statesman explained the difficult choices facing the country in plain language.","translation":"这位政治家没有利用公众焦虑，而是用通俗的语言解释了国家面临的艰难抉择。","targetForm":"statesman","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A respected statesman can turn a tense negotiation into a practical search for common ground.","translation":"受人尊敬的政治家能够把紧张的谈判转变为务实地寻找共同点。","targetForm":"statesman","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When the debate became partisan, the elder statesman reminded both sides of their responsibility to future generations.","translation":"当辩论变得党派化时，这位资深政治家提醒双方要对后代负责。","targetForm":"statesman","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The biography portrays the statesman as a patient listener whose influence depended on preparation rather than spectacle.","translation":"这部传记把这位政治家描绘成耐心的倾听者；他的影响力来自充分准备，而非哗众取宠。","targetForm":"statesman","senseId":"source-n-1","sourceSenseId":"n-1"}]},"string":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"细绳"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"一串"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"字符串"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"串起"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"线"}],"examples":[{"sentence":"She tied the label to the sample with a length of string so that it would not be separated during transport.","translation":"她用一段细绳把标签系在样本上，以免运输途中分开。","targetForm":"string","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"A string of delayed payments forced the charity to postpone repairs, even though the building had become unsafe.","translation":"一连串延迟付款迫使慈善机构推迟维修，尽管建筑已经变得不安全。","targetForm":"string","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The database rejected the string because it contained a character that the older system could not interpret.","translation":"数据库拒绝了该字符串，因为其中含有旧系统无法识别的字符。","targetForm":"string","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The curator strung the small lights across the entrance, which made the evening exhibition easier to find.","translation":"馆长把小灯串挂在入口处，使晚间展览更容易找到。","targetForm":"strung","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Before the performance, the musician checked each string carefully because humidity had altered the instrument's tuning.","translation":"演出前，音乐家仔细检查每根弦，因为湿度改变了乐器音准。","targetForm":"string","senseId":"source-n-1","sourceSenseId":"n-1"}]},"steady":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"稳定的"},{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"坚定的"},{"id":"source-adj-6","partOfSpeech":"adj.","sourceSenseIds":["adj-6"],"sense":"经常的"}],"examples":[{"sentence":"A steady decline in the unemployment rate indicates that the economy is recovering from the recession.","translation":"失业率的稳步下降表明经济正在从衰退中复苏。","targetForm":"steady","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the project encountered numerous setbacks, the team's steady commitment to quality ensured its eventual success.","translation":"尽管项目遇到了许多挫折，但团队对质量的坚定承诺确保了其最终的成功。","targetForm":"steady","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"Because she maintained a steady study schedule throughout the semester, she felt confident and well-prepared for the final exams.","translation":"因为她在整个学期保持了稳定的学习计划，所以她对期末考试感到自信且准备充分。","targetForm":"steady","senseId":"source-adj-6","sourceSenseId":"adj-6"},{"sentence":"Investors prefer companies with a steady dividend payout, which signals financial stability and reliable management.","translation":"投资者偏好有稳定股息支付的公司，这标志着财务稳定和可靠的管理。","targetForm":"steady","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"strive":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"努力"}],"examples":[{"sentence":"Companies that strive for innovation often invest heavily in research and development, which drives long-term growth.","translation":"努力创新的公司通常在研发上投入巨资，这推动了长期增长。","targetForm":"strive","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Individuals who strive for personal excellence often set challenging goals, thereby pushing beyond their comfort zones.","translation":"追求个人卓越的人通常设定具有挑战性的目标，从而超越自己的舒适区。","targetForm":"strive","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although resources are limited, educators must strive to provide equitable learning opportunities for all students.","translation":"尽管资源有限，教育者必须努力为所有学生提供公平的学习机会。","targetForm":"strive","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"To ensure sustainable development, nations must strive to balance economic growth with environmental protection.","translation":"为了确保可持续发展，各国必须努力平衡经济增长与环境保护。","targetForm":"strive","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"While governments strive to reduce unemployment, structural changes in the economy can hinder progress.","translation":"虽然政府努力降低失业率，但经济结构的变化可能阻碍进展。","targetForm":"strive","senseId":"source-v-1","sourceSenseId":"v-1"}]},"stay":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"停留"}],"examples":[{"sentence":"The Palestinian side, for its part, must accept that Israel is here to stay, and that huge benefits can be reaped from economic cooperation.","translation":"在巴勒斯坦方，必须接受以色列已在这里定居的现实，并意识到经济合作可以带来巨大的好处。","targetForm":"stay","senseId":"source-n-1","sourceSenseId":"n-1"}]},"steam":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"蒸汽"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"精力"}],"examples":[{"sentence":"The result of the invention of the steam engine was that human power was replaced by mechanical power.","translation":"机械力代替人力, 这是蒸汽机发明的结果。","targetForm":"steam","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"It's very important to know how to let off steam, living in this world.","translation":"生活在这个世界里，懂得发泄是十分重要的。","targetForm":"steam","senseId":"source-n-2","sourceSenseId":"n-2"}]},"style":{"senseGroups":[{"id":"source-n-7","partOfSpeech":"n.","sourceSenseIds":["n-7"],"sense":"样式"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"风格"}],"examples":[{"sentence":"She weaves her baskets in the same style as her ancestors who lived in the desert and harvested fruit and vegetables.","translation":"她编织的篮子的样式，与她生活在沙漠中收获水果和蔬​​菜的祖先相同。","targetForm":"style","senseId":"source-n-7","sourceSenseId":"n-7"},{"sentence":"Pizza is the kind of food that fits into today's life style.","translation":"比萨是种适合现在的生活方式的食物。","targetForm":"style","senseId":"source-n-1","sourceSenseId":"n-1"}]},"stab":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"尝试"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"剧痛"}],"examples":[{"sentence":"She made a stab at explaining the complex theory to the audience, using simple analogies to ensure clarity.","translation":"她尝试向观众解释这个复杂的理论，用简单的类比来确保清晰。","targetForm":"stab","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Because the deadline was approaching, the team took a stab at completing the project, even though resources were limited.","translation":"由于截止日期临近，团队尝试完成项目，尽管资源有限。","targetForm":"stab","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"When the startup failed, the investors felt a sharp stab of disappointment, which prompted them to reassess their strategy.","translation":"当创业公司失败时，投资者们感到一阵强烈的失望，这促使他们重新评估自己的策略。","targetForm":"stab","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Although he had no formal training, he decided to take a stab at writing a novel during his summer break.","translation":"尽管他没有受过正规训练，他还是决定在暑假期间尝试写一部小说。","targetForm":"stab","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The sudden stab of pain in his chest made him realize that he had been neglecting his health for too long.","translation":"胸口突然的刺痛使他意识到自己忽视健康太久了。","targetForm":"stab","senseId":"source-n-3","sourceSenseId":"n-3"}]},"stun":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"使震惊"}],"examples":[{"sentence":"They're creating stunning works of art to force people to stop and appreciate the beauty of the universe.","translation":"他们创作出令人惊叹的艺术作品，从而让人们驻足欣赏宇宙之美。","targetForm":"stunning","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Thousands of laborers and craftsmen toiled for 22 years to craft the stunning white marble edifice.","translation":"数千名工人和工匠辛勤工作了 22 年，才打造出这座令人惊叹的白色大理石建筑。","targetForm":"stunning","senseId":"source-v-2","sourceSenseId":"v-2"}]},"strip":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"带"}],"examples":[{"sentence":"TEL AVIV – Finally, the long-sought truce between Israel and Hamas in the Gaza Strip has become a reality.","translation":"特拉维夫－终于，期盼已久的以色列和哈马斯在加沙地带上的停战变成了现实。","targetForm":"strip","senseId":"source-n-3","sourceSenseId":"n-3"}]},"statute":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"法规"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"成文法律"}],"examples":[{"sentence":"Although the statute was enacted to protect consumer rights, its enforcement has been inconsistent across different regions.","translation":"尽管该法规旨在保护消费者权益，但其在不同地区的执行情况并不一致。","targetForm":"statute","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because the statute imposes strict liability on manufacturers, companies must ensure their products meet all safety standards.","translation":"由于该法规对制造商施加严格责任，公司必须确保其产品符合所有安全标准。","targetForm":"statute","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The statute not only defines the penalties for corporate fraud but also establishes a framework for whistleblower protection.","translation":"该法规不仅定义了公司欺诈的处罚，还建立了举报人保护框架。","targetForm":"statute","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The statute, which was passed unanimously by the legislature, represents a significant shift in environmental policy.","translation":"该法规由立法机构一致通过，代表了环境政策的重大转变。","targetForm":"statute","senseId":"source-n-2","sourceSenseId":"n-2"}]},"strengthen":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"变强"}],"examples":[{"sentence":"Europe clearly would be better off with Chirac weakened than strengthened, even if it means a temporary slowing of the pace of integration.","translation":"显然，势力削弱的希拉克比势力强大的他对欧洲更为有利，即使这意味着欧洲整合的进程将暂时放缓脚步。","targetForm":"strengthened","senseId":"source-v-3","sourceSenseId":"v-3"}]},"street":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"街道"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"街区"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"街道的"}],"examples":[{"sentence":"The narrow street was redesigned with wider pavements so that children and older residents could move safely.","translation":"这条狭窄街道被重新设计为更宽的人行道，让儿童和年长居民能安全通行。","targetForm":"street","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the street is busy at noon, delivery vehicles are restricted during the hours when schools close.","translation":"尽管这条街中午很繁忙，学校放学时段会限制配送车辆通行。","targetForm":"street","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A lively street can encourage neighbours to meet informally, provided that benches and shade are available.","translation":"充满活力的街区能鼓励邻居非正式相聚，前提是有长椅和遮阳。","targetForm":"street","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The project collected street interviews to understand how shopkeepers viewed the proposed changes to parking.","translation":"该项目收集街头访谈，以了解商户如何看待拟议的停车调整。","targetForm":"street","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because street lighting was uneven, the council asked residents to identify places that felt unsafe after dark.","translation":"由于街道照明不均，市政部门请居民标出入夜后感觉不安全的地点。","targetForm":"street","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"stick":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"棍"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"条状物"}],"examples":[{"sentence":"My friend has had three jobs in a year; he never sticks to anything for long.","translation":"我的朋友总是三分钟热度，一年就换了三份工作。","targetForm":"sticks","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I'm running a little short on time, so I can only go out and buy flat bread and bread sticks.","translation":"我时间有点来不及，只能出门买大饼油条。","targetForm":"sticks","senseId":"source-n-6","sourceSenseId":"n-6"}]},"staircase":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"楼梯"}],"examples":[{"sentence":"The staircase was fitted with a handrail on both sides so that visitors could move between floors confidently.","translation":"楼梯两侧都安装了扶手，让访客能有把握地在楼层间通行。","targetForm":"staircase","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the staircase occupied little space, a skylight above it brought daylight into the centre of the house.","translation":"尽管楼梯占用空间很小，它上方的天窗仍把日光带入房屋中心。","targetForm":"staircase","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The architect designed the staircase with shallow steps because the building would be used by people of many ages.","translation":"建筑师把楼梯设计成较浅的台阶，因为这栋楼将供不同年龄的人使用。","targetForm":"staircase","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"At the top of the staircase, a reading corner gave students a quiet place to wait between classes.","translation":"楼梯顶端设有阅读角，为学生在课间等候提供安静场所。","targetForm":"staircase","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Before restoring the old staircase, the team recorded every damaged step and section of the original railing.","translation":"修复旧楼梯前，团队记录了每一级受损台阶和原始栏杆部分。","targetForm":"staircase","senseId":"source-n-1","sourceSenseId":"n-1"}]},"stamp":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"邮票"}],"examples":[{"sentence":"Please don't forget to put a stamp on the letter before mailing it.","translation":"请不要忘记寄信前要在上面贴邮票。","targetForm":"stamp","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"I don't have a stamp collection, but I have a Japanese postcard collection that I could use as an excuse to invite him.","translation":"我没有集邮，但是却收藏了一堆日本的明信片，我想我可以用这来做借口，邀请他来我家。","targetForm":"stamp","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Bob gave Tina almost all the stamps he had collected, and kept only a few for himself.","translation":"鲍勃几乎把他所收集的所有邮票给了缇娜，只留了一点给他自己。","targetForm":"stamps","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"I would like to have a look at your collection of stamps.","translation":"我想看看您的邮票收藏。","targetForm":"stamps","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Put this stamp on the postcard and drop it in the mailbox.","translation":"把这张邮票贴在明信片上，然后投到邮箱里。","targetForm":"stamp","senseId":"source-n-2","sourceSenseId":"n-2"}]},"static":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"静电"}],"examples":[{"sentence":"A static website, which lacks interactive features, may not engage users as effectively as a dynamic one.","translation":"缺乏交互功能的静态网站可能不如动态网站那样有效吸引用户。","targetForm":"static","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Engineers must consider static loads, which include the weight of the structure itself, to ensure stability.","translation":"工程师必须考虑包括结构自身重量在内的静荷载，以确保稳定性。","targetForm":"static","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When a character remains static throughout a novel, readers may find the story less compelling.","translation":"当角色在整部小说中保持静止不变时，读者可能会觉得故事不那么引人入胜。","targetForm":"static","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although static electricity is often harmless, it can ignite flammable gases in industrial settings.","translation":"尽管静电通常无害，但在工业环境中它可能点燃易燃气体。","targetForm":"static","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the population remained static for decades, the government introduced incentives to encourage growth.","translation":"由于人口几十年来保持不变，政府推出了激励措施以鼓励增长。","targetForm":"static","senseId":"source-n-1","sourceSenseId":"n-1"}]},"sticky":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"有粘性的"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"粘的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"顽固的"}],"examples":[{"sentence":"Although the label was designed to be removable, it left a sticky residue that required alcohol to clean.","translation":"尽管标签被设计为可移除，但它留下了粘性残留物，需要用酒精清洁。","targetForm":"sticky","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because the dough was too sticky, the baker added more flour to achieve the right consistency.","translation":"因为面团太粘，面包师添加了更多面粉以达到合适的稠度。","targetForm":"sticky","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"When the negotiations entered a sticky phase, the mediator proposed a temporary break to reduce tension.","translation":"当谈判进入棘手阶段时，调解员提议暂时休会以缓和紧张气氛。","targetForm":"sticky","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Despite the central bank's efforts, inflation proved sticky, which forced a revision of economic forecasts.","translation":"尽管央行做出了努力，通货膨胀仍居高不下，这迫使经济预测进行修订。","targetForm":"sticky","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The sticky weather made the outdoor event uncomfortable, thereby reducing attendance significantly.","translation":"湿热的天气使户外活动令人不适，从而显着减少了出席人数。","targetForm":"sticky","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"staple":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"常用品"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"主要产物"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"主要要素"}],"examples":[{"sentence":"While digital media have transformed communication, television remains a staple of family entertainment, thereby preserving shared viewing experiences.","translation":"尽管数字媒体改变了通信方式，电视仍然是家庭娱乐的主要形式，从而保留了共同的观看体验。","targetForm":"staple","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although rice is a staple food in many Asian countries, its cultivation requires substantial water resources, which can strain local supplies.","translation":"尽管大米是许多亚洲国家的主食，但其种植需要大量水资源，这可能会给当地供应带来压力。","targetForm":"staple","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because wheat serves as a staple crop in this region, farmers rely on stable weather patterns to ensure a successful harvest.","translation":"由于小麦是该地区的主要作物，农民依赖稳定的天气模式来确保丰收。","targetForm":"staple","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The library's collection includes staple works of Western philosophy, which students are encouraged to read during their first year to build a strong foundation.","translation":"图书馆的馆藏包括西方哲学的主要著作，鼓励学生在第一年阅读这些作品以打下坚实基础。","targetForm":"staple","senseId":"source-n-3","sourceSenseId":"n-3"}]},"stop":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"停止"}],"examples":[{"sentence":"The truth is that trafficking will stop only when the need for organs disappears.","translation":"事实是：只有不需要器官的时候，走私才能停止。","targetForm":"stop","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The campaigners claim we must stop economic growth because the planet is crossing environmental boundaries, and inequality between humans is increasing.","translation":"这些活动人士声称我们必须停止经济增长，因为地球正在超越环境的承载能力，人们之间的不平等状况也不断恶化。","targetForm":"stop","senseId":"source-n-1","sourceSenseId":"n-1"}]},"staff":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"工作班子"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"全体人员"}],"examples":[{"sentence":"But this argument’s intellectual foundations – first laid out in a 2002 paper by 13 members of the Fed’s Washington, DC, research staff – are shaky, at best.","translation":"但该理论的思想基础 — — 其根源可以追溯到华盛顿美联储研究团队2002年的一篇论文 — — 大有问题。","targetForm":"staff","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The staff in that restaurant gave us a very good impression.","translation":"那家饭馆儿的服务员给我们留下很好的印象。","targetForm":"staff","senseId":"source-n-1","sourceSenseId":"n-1"}]},"stake":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"赌注"}],"examples":[{"sentence":"Europe’s policy for Iran is not regime change, but when human rights and democracy are at stake, we cannot simply close our eyes.","translation":"欧洲对伊朗的政策不是实现政权更替，但当人权和民主告急之时，我们可不能无动于衷，袖手旁观。","targetForm":"stake","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Finally, Council meetings should be open when legislative matters are at stake, so that citizens can know who voted for what and according to which criteria.","translation":"最后，当立法无法奏效的时候，就应该召开欧盟理事会会议，这样公民们就能知道谁该根据哪种标准为什么投票。","targetForm":"stake","senseId":"source-n-4","sourceSenseId":"n-4"}]},"stride":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"进步"}],"examples":[{"sentence":"Under the teacher's guidance, I took big strides with my studies.","translation":"在老师的指导下，我的学习有了很大的进步。","targetForm":"strides","senseId":"source-n-4","sourceSenseId":"n-4"}]},"stream":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"小河"}],"examples":[{"sentence":"Behind his house is a stream so clear that you can see the bottom of it.","translation":"他家后面有小溪，清可见底。","targetForm":"stream","senseId":"source-n-2","sourceSenseId":"n-2"}]},"stroke":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"笔划"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"中风"}],"examples":[{"sentence":"It's a lot of trouble to write my name, because it takes 50 strokes to write both my first and last names.","translation":"我的姓、名一共有五十划，写起来麻烦得很。","targetForm":"strokes","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"An elderly person in my family suddenly fell to the ground; he likely suffered a stroke.","translation":"我家里有个老年人突然倒在地上，大概是中风了。","targetForm":"stroke","senseId":"source-n-3","sourceSenseId":"n-3"}]},"strength":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"实力"}],"examples":[{"sentence":"After winning the presidency, Chen could have risen above theatrics by focusing on two Taiwanese strengths: its economy and its unbroken humanist Chinese cultural tradition.","translation":"在赢得总统选举后，陈本可以依靠集中力量关注台湾的两个强项，也就是它的经济和它未遭到破坏的人文主义的中国文化传统来提升他的地位。","targetForm":"strengths","senseId":"source-n-2","sourceSenseId":"n-2"}]},"stroll":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"闲逛"}],"examples":[{"sentence":"When I first came to Beijing, I loved to stroll everywhere, but Beijing was not like what I had imagined.","translation":"我先来北京时，就去哪里都爱逛街，可是北京跟我想象的不一样。","targetForm":"stroll","senseId":"source-n-1","sourceSenseId":"n-1"}]},"stress":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"压力"}],"examples":[{"sentence":"When you're about to have exams, lifting weights really does relieve stress, and it's also good for your mind and body.","translation":"快要考试的时候，举重真的消愁解闷，再说对身体和精神都很好。","targetForm":"stress","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"There has been a lot of stress at work lately.","translation":"最近工作压力太大了。","targetForm":"stress","senseId":"source-n-1","sourceSenseId":"n-1"}]},"state":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"国家"}],"examples":[{"sentence":"Now, that is a principle upon which the United States, and any republic, should stand.","translation":"现在，这恰恰就是美国以及任何共和国应当遵守的原则。","targetForm":"states","senseId":"source-n-4","sourceSenseId":"n-4"}]},"steal":{"senseGroups":[{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"偷偷地行动"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"偷窃"}],"examples":[{"sentence":"Every night, when all was quiet, he would steal into his neighbour's garden to scrump an apple.","translation":"每天晚上，当周围安静下来，他就会偷溜进邻居的花园里偷走一颗苹果。","targetForm":"steal","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"I'll let you off this time, but I don't ever want to catch you stealing again.","translation":"今次就原谅你吧，但我不希望再看见你偷东西。","targetForm":"stealing","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Tom was stealing money for the last two years, and Mary knew it all the time.","translation":"过去两年以来汤姆都在偷钱，而且这段时间里玛莉都知道。","targetForm":"stealing","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Sleep is the greatest thief, for it steals half one's life.","translation":"睡眠是最大的小偷，它偷了我们一半的生命。","targetForm":"steals","senseId":"source-v-3","sourceSenseId":"v-3"}]},"stimulate":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"刺激"}],"examples":[{"sentence":"The responsibility for stimulating the economy in the next downturn will therefore fall to fiscal policy – changes in taxes and government spending.","translation":"因此，在下一次衰退中，刺激经济的重任降落在财政政策上 — — 即税收和政府支出的变化。","targetForm":"stimulating","senseId":"source-v-1","sourceSenseId":"v-1"}]},"stuff":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"东西"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"织品"}],"examples":[{"sentence":"Or it may be that the greatest happiness of all comes from not having to worry about stuff like this.","translation":"或者，说到底，最大的幸福来自不再担心这一问题。","targetForm":"stuff","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Old stuff that doesn't fit any more can be used as cloths.","translation":"不合适的旧衣物可以当抹布用。","targetForm":"stuff","senseId":"source-n-6","sourceSenseId":"n-6"}]},"stir":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"搅动"}],"examples":[{"sentence":"Two women wielding giant spatulas continuously stir a brimming wok of shredded beef simmering in curry sauce.","translation":"两名女子挥舞着巨大的锅铲，不停地翻炒着盛满咖哩酱汁的牛肉丝。","targetForm":"stir","senseId":"source-n-3","sourceSenseId":"n-3"}]},"stripe":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"条纹"}],"examples":[{"sentence":"The Indian flag is called the tricolour because it has stripes of three colours – saffron, white and green.","translation":"印度国旗叫做「三色旗」，因为它是由三条不同颜色的色条组成的 ﹣ 橙黄色、白色和绿色。","targetForm":"stripes","senseId":"source-n-2","sourceSenseId":"n-2"}]},"standard":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"本位"}],"examples":[{"sentence":"There are three differences between the euro and the gold standard – none of which is particularly reassuring at this moment.","translation":"欧元制和金本位制有三个不同点，可是现在，没有一点能让人从中得到安慰。","targetForm":"standard","senseId":"source-n-5","sourceSenseId":"n-5"}]},"stretch":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"伸展"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"连绵"}],"examples":[{"sentence":"You have to stretch your muscles after swimming in the pool.","translation":"在泳池游完泳后要拉伸肌肉。","targetForm":"stretch","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"On the border, there is a stretch of agricultural land.","translation":"边境上有一片农业区。","targetForm":"stretch","senseId":"source-n-3","sourceSenseId":"n-3"}]},"stock":{"senseGroups":[{"id":"source-n-8","partOfSpeech":"n.","sourceSenseIds":["n-8"],"sense":"股票"}],"examples":[{"sentence":"Nor are these claims based on the Chinese stock market, which has generally followed a downward path over the past few years.","translation":"过热的说法也并非以股市为依据，因为过去几年来，股市一直处于下降通道之中。","targetForm":"stock","senseId":"source-n-8","sourceSenseId":"n-8"},{"sentence":"So, while this latest bear-market rally may continue for a bit longer, renewed downward pressure on stocks and other risky assets is inevitable.","translation":"因此，尽管最近这次熊市反弹将持续更长时间，但股票和其他风险性资产必将重新感受到向下的压力。","targetForm":"stocks","senseId":"source-n-8","sourceSenseId":"n-8"}]},"storage":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"储藏"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"存储器"}],"examples":[{"sentence":"Another powerful measure would be to protect and restore natural ecosystems, which could result in the storage of 220-330 gigatons of CO2 worldwide .","translation":"另一项强力措施是保护和重建自然生态系统，这样可以储存2,200—3,300亿吨二氧化碳。","targetForm":"storage","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"My phone needs to have enough storage for my apps.","translation":"我的手机需要足够存储空间来下载 App。","targetForm":"storage","senseId":"source-n-1","sourceSenseId":"n-1"}]},"step":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"步骤"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"步"}],"examples":[{"sentence":"And yet, for all the woe, a resolution remains possible; to achieve it, five steps must be taken without delay.","translation":"但尽管局势如此痛苦，仍然保留着和平解决的生机；要想实现这个目标，必须立即实行五步走政策。","targetForm":"steps","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Second, most Palestinians perceived that their ability to go through such a democratic process was itself a significant step in their struggle against Israel.","translation":"其次，大多数巴勒斯坦人将他们是否能实现这样一个民主进本身看作反对以色列占领斗争中的关键一步。","targetForm":"step","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Unless Piketty’s right-wing critics step up their game and actually make some valid points, that will be the default judgment on his book.","translation":"除非皮凯蒂的右翼批评者实际拿出某些有效的观点，人们将如此缺省认知皮凯蒂的著作，这样的看法无论多少红色诱饵和抹黑法国都改变不了。","targetForm":"step","senseId":"source-n-2","sourceSenseId":"n-2"}]},"stupid":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"愚蠢的"}],"examples":[{"sentence":"It is because light travels faster than sound that some people look brilliant before sounding stupid.","translation":"光速比音速快，所以某些人在开口前，看起来还挺聪明的。","targetForm":"stupid","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"I don't think Tom and Mary know that John thinks they're stupid.","translation":"我不觉得汤姆和玛丽知道约翰认为他们愚蠢。","targetForm":"stupid","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"I didn't think Tom would be stupid enough to do that.","translation":"我觉得，汤姆不会傻到那样做。","targetForm":"stupid","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The fundamental cause of the trouble is that in the modern world the stupid are cocksure while the intelligent are full of doubt.","translation":"问题的根源是，在当今世界，愚人充满了自信，而智者充满了怀疑。","targetForm":"stupid","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Between you and me, I think our boss is stupid.","translation":"我觉得我们老板很蠢，这我就只跟你说。","targetForm":"stupid","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"stadium":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"露天大型运动场"}],"examples":[{"sentence":"The day after tomorrow, I plan to go to the baseball stadium to watch a baseball game.","translation":"我后天打算去棒球场看一场棒球比赛。","targetForm":"stadium","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the stadium is not far from my house, I often go to football games.","translation":"因为体育场离我家不远，我往往去看足球赛。","targetForm":"stadium","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Let's go to the stadium, because today's match will not be televised.","translation":"一起去体育馆吧，因为今天的比赛没有电视转播。","targetForm":"stadium","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"There were a lot of excited fans in the stadium.","translation":"体育场里有很多兴奋的球迷。","targetForm":"stadium","senseId":"source-n-1","sourceSenseId":"n-1"}]},"stage":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"舞台"}],"examples":[{"sentence":"This puts a new debate center stage: how to reconcile increased action to reduce greenhouse gas emissions with strong economic growth.","translation":"这把一个新争论带到了舞台中央：如何协调越来越多的行动以降低伴随强劲经济增长出现的温室气体排放。","targetForm":"stage","senseId":"source-n-2","sourceSenseId":"n-2"}]},"strange":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"奇怪的"},{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"不可思议的"},{"id":"source-adj-8","partOfSpeech":"adj.","sourceSenseIds":["adj-8"],"sense":"异乡的"}],"examples":[{"sentence":"It is strange that he should be put up at such a cheap hotel.","translation":"真奇怪，他竟然被安排入住这种廉价酒店。","targetForm":"strange","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The plane was about to take off when I heard a strange sound.","translation":"飞机快要起飞的时候，我听到了一个奇怪的声音。","targetForm":"strange","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"When it got dark, the scenery became strange and spooky.","translation":"天黑之后，景色变得诡异阴森。","targetForm":"strange","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"As a stranger in a strange land, the sporadic solicitude from friends can be especially heart-warming.","translation":"在异乡生活，偶尔收到朋友的关怀让人倍感温暖。","targetForm":"strange","senseId":"source-adj-8","sourceSenseId":"adj-8"}]},"storm":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"风暴"}],"examples":[{"sentence":"Our shared objective is clear: to ensure that Africa not only weathers the immediate storm, but emerges from it stronger.","translation":"我们共同的目标是明确的，那就是确保非洲不仅度过当前的风暴，而且之后更加强大。","targetForm":"storm","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The perfect storm is forming because both Europe and America, for different reasons, are following monetary policies that encourage the euro to rocket to dangerous levels.","translation":"由于欧洲和美国由于不同的原因正在采取鼓励欧元大幅升值到危险水平的货币政策，因此，一场完美风暴正在形成。","targetForm":"storm","senseId":"source-n-4","sourceSenseId":"n-4"}]},"stem":{"senseGroups":[{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"堵塞物"}],"examples":[{"sentence":"The risk that imperial hubris accelerates, rather than stems, Islamist terror is all too real – yet again.","translation":"帝国傲慢可能再一次助长而不是遏制伊斯兰恐怖主义，这一风险是实实在在的。","targetForm":"stems","senseId":"source-n-6","sourceSenseId":"n-6"}]},"strategy":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"战略"}],"examples":[{"sentence":"To meet this challenge, we have designed an economic strategy that rests on three pillars: Europe, fiscal consolidation, and competitiveness.","translation":"为了面对这一挑战，我们设计了基于三大基石的经济战略：欧洲、财政整合和竞争力。","targetForm":"strategy","senseId":"source-n-1","sourceSenseId":"n-1"}]},"stand":{"senseGroups":[{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"立场"}],"examples":[{"sentence":"Now, that is a principle upon which the United States, and any republic, should stand.","translation":"现在，这恰恰就是美国以及任何共和国应当遵守的原则。","targetForm":"stand","senseId":"source-n-6","sourceSenseId":"n-6"}]},"story":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"故事"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"描述"}],"examples":[{"sentence":"That is the most important message for everyone, atheists included, to take from the Christian story of Christmas.","translation":"所有人，包括无神论者，都应该从基督的圣诞故事中领会这种最重要的精神涵义。","targetForm":"story","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"That our profligate consumption requires five planets is a catchy story, but it is wrong.","translation":"比约恩·隆姆博格，哥本哈根共识中心的主任，是哥本哈根商学院兼职教授，着有《怀疑主义环保分子并请冷静：怀疑主义环保分子之全球变暖指南 》 。","targetForm":"story","senseId":"source-n-4","sourceSenseId":"n-4"}]},"stack":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"堆叠"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"烟囱"}],"examples":[{"sentence":"She's a professor whose works you could stack up to head height.","translation":"那位是一个著作等身的教授。","targetForm":"stack","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tom is clambering about on the roof, repairing the chimney stack.","translation":"汤姆在屋顶一边爬一边修理烟囱。","targetForm":"stack","senseId":"source-n-6","sourceSenseId":"n-6"}]},"startle":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"惊愕"}],"examples":[{"sentence":"Avoid sudden movements around the rabbit, they can startle them.","translation":"避免在兔子旁边突然做出动作，以免吓到牠们。","targetForm":"startle","senseId":"source-n-1","sourceSenseId":"n-1"}]},"stereotype":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"陈规"}],"examples":[{"sentence":"It is a stereotype that police officers always eat doughnuts.","translation":"警察总吃甜甜圈是一种刻板印象。","targetForm":"stereotype","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The stage charisma of drag performers compels audiences to reconsider their own stereotypes.","translation":"反串秀者的舞台魅力使观众不禁重新审视自己的刻板印象。","targetForm":"stereotypes","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"This film attempts to break stereotypes and redefine what true masculinity is.","translation":"这部电影试图打破刻板印象，重新诠释何谓真正的男性特质。","targetForm":"stereotypes","senseId":"source-n-2","sourceSenseId":"n-2"}]},"struggle":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"斗争"}],"examples":[{"sentence":"Second, most Palestinians perceived that their ability to go through such a democratic process was itself a significant step in their struggle against Israel.","translation":"其次，大多数巴勒斯坦人将他们是否能实现这样一个民主进本身看作反对以色列占领斗争中的关键一步。","targetForm":"struggle","senseId":"source-n-1","sourceSenseId":"n-1"}]},"statement":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"陈述"}],"examples":[{"sentence":"Such statements sounded new to Chinese ears, because they accentuated politics rather than trumpeting the Party’s usual emphasis on economic determinism.","translation":"这些说法对于今天的中国人来说相当新鲜的，因为这些说法都是强调政治因素的重要性，而非党以往经常强调的经济决定论。","targetForm":"statements","senseId":"source-n-1","sourceSenseId":"n-1"}]},"statistical":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"统计的"}],"examples":[{"sentence":"So, if you have ever sat at somebody’s deathbed, the answer may very well be yes: you sat at the deathbed of a statistical life.","translation":"因此如果你亲身经历过垂死的场面，其实多数人都有过这样的经历：你也就看到过统计生命的行将消失。","targetForm":"statistical","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"stone":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"石头"}],"examples":[{"sentence":"We study a species of poisonous frog that looks very similar to a stone.","translation":"我们研究一种和石头长得很像的毒青蛙。","targetForm":"stone","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A water drop hollows a stone not by force but by falling often.","translation":"滴水穿石，不是靠力量，而是靠时间。","targetForm":"stone","senseId":"source-n-1","sourceSenseId":"n-1"}]}}};
